<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from "vue";
import {
  getArtifactCatalog,
  getArtifactWorkbookUrl,
  type ArtifactCatalogEntry,
} from "../../data/artifactCatalog";
import XlsxSheet from "../../components/playground/XlsxSheet.vue";
import {
  getWorkbookThumb,
  loadWorkbookPreview,
  parseCellRef,
} from "../../components/playground/xlsx";
import { prefersReducedMotion } from "../../components/landing/bp";

useBlueprintPage();
useSeo({
  title: "Artifact Playground",
  description:
    "Real workbooks generated by typed-xlsx, drawn in the browser next to the schema that produced them.",
  type: "website",
});

const catalog = getArtifactCatalog();
const tour = catalog.find((a) => a.id === "kitchen-sink");
const others = catalog.filter((a) => a.id !== "kitchen-sink");
const kb = (bytes?: number) => (bytes ? `${(bytes / 1024).toFixed(1)} KB` : "");

/* ---------- the kitchen sink as a drawer of its sheets ---------- */
const { data: tourModel } = await useAsyncData("workbook-preview:kitchen-sink", () =>
  loadWorkbookPreview("kitchen-sink"),
);
type Plate = { name: string; track: string; fg: string; bg: string };
const plates = computed<Plate[]>(() => {
  const names = tour?.inspectSummary?.sheetNames ?? [];
  const map = tourModel.value?.sheets[0];
  // the feature map lists every tab with its track badge: column A = track, column C = tab name
  const trackOf = new Map<string, { track: string; fg: string; bg: string }>();
  if (map && tourModel.value) {
    for (const [cellRef, cell] of Object.entries(map.cells)) {
      const p = parseCellRef(cellRef);
      if (!p || p.c !== 3 || p.r < 3) continue;
      const badge = map.cells[`A${p.r}`];
      const style = badge?.s != null ? tourModel.value.styles[badge.s] : undefined;
      if (badge?.v)
        trackOf.set(cell.v, {
          track: badge.v,
          fg: style?.c ?? "#334155",
          bg: style?.f ?? "#e2e8f0",
        });
    }
  }
  return names.map((name) => ({
    name,
    ...(trackOf.get(name) ?? { track: "Workbook", fg: "#92400e", bg: "#fef3c7" }),
  }));
});
const pulled = ref(6);
let auto = true;
let timer: ReturnType<typeof setTimeout> | null = null;
function pull(i: number, stop = false) {
  pulled.value = i;
  if (stop) {
    auto = false;
    if (timer) clearTimeout(timer);
  }
}
function loop() {
  if (!auto || !plates.value.length) return;
  pulled.value = (pulled.value + 1) % plates.value.length;
  timer = setTimeout(loop, 1900);
}
onMounted(() => {
  if (!prefersReducedMotion()) timer = setTimeout(loop, 1900);
});
onBeforeUnmount(() => timer && clearTimeout(timer));

/* ---------- catalog ---------- */
const has = (a: ArtifactCatalogEntry, ...features: string[]) =>
  features.some((f) => a.features.includes(f));
const FILTERS: Array<{ key: string; label: string; test: (a: ArtifactCatalogEntry) => boolean }> = [
  { key: "all", label: "All", test: () => true },
  { key: "buffered", label: "Buffered", test: (a) => !has(a, "createWorkbookStream") },
  { key: "streaming", label: "Streaming", test: (a) => has(a, "createWorkbookStream") },
  { key: "table", label: "Excel table", test: (a) => has(a, "excel-table mode") },
  { key: "subrows", label: "Sub-rows", test: (a) => has(a, "sub-row expansion") },
  {
    key: "renderers",
    label: "Renderers",
    test: (a) =>
      has(a, "badge renderer", "image columns", "sparkline renderer", "renderer columns"),
  },
  {
    key: "workflow",
    label: "Workflow",
    test: (a) => has(a, "validation DSL", "sheet protection", "conditional styles"),
  },
];
const filter = ref("all");
const activeTest = computed(() => FILTERS.find((f) => f.key === filter.value)!.test);
const kindLabel = (a: ArtifactCatalogEntry) => {
  if (has(a, "createWorkbookStream")) return "createWorkbookStream()";
  if (has(a, "excel-table mode")) return 'mode: "excel-table"';
  if (has(a, "dynamic columns")) return '.dynamic("…")';
  if (has(a, "validation DSL")) return "validation DSL";
  if (has(a, "image columns")) return 'type: "image"';
  return "createWorkbook()";
};
const cards = others.map((a) => ({ a, thumb: getWorkbookThumb(a.id) }));
const tourThumb = getWorkbookThumb("kitchen-sink");
</script>

<template>
  <div class="bp bp-pg">
    <section class="pg-head wrap">
      <h1 class="h1">Real workbooks.<br /><span class="accent">Schema included.</span></h1>
      <p class="lede">
        {{ catalog.length }} .xlsx files generated by typed-xlsx and drawn right here in your
        browser. Open one to read the schema that produced it, inspect any cell's OOXML, or download
        the file.
      </p>
    </section>

    <section class="wrap cat">
      <div class="cat-head">
        <h2 class="h3">Real-world reports</h2>
        <div class="filters" role="group" aria-label="Filter exports">
          <button
            v-for="f in FILTERS"
            :key="f.key"
            type="button"
            :class="{ on: filter === f.key }"
            :aria-pressed="filter === f.key"
            @click="filter = f.key"
          >
            {{ f.label }} <span>{{ others.filter(f.test).length }}</span>
          </button>
        </div>
      </div>
      <div class="agrid">
        <NuxtLink
          v-for="{ a, thumb } in cards"
          :key="a.id"
          :to="`/playground/${a.id}`"
          class="acard"
          :class="{ hide: !activeTest(a) }"
        >
          <div class="thumb">
            <span class="corner tl" /><span class="corner br" />
            <div class="mini">
              <XlsxSheet
                v-if="thumb && thumb.sheets[0]"
                :sheet="thumb.sheets[0]"
                :styles="thumb.styles"
                :dxfs="thumb.dxfs"
                compact
                :zoom="0.62"
                :clip-width="470"
              />
            </div>
          </div>
          <div class="ameta">
            <div class="kind">{{ kindLabel(a) }}</div>
            <h3>{{ a.title }}</h3>
            <p>{{ a.description }}</p>
            <div class="af">
              <span
                >{{ a.inspectSummary?.sheetNames.length ?? 1 }} sheet{{
                  (a.inspectSummary?.sheetNames.length ?? 1) > 1 ? "s" : ""
                }}, {{ kb(thumb?.fileSize) }}</span
              ><UIcon name="i-lucide-arrow-right" class="ic" />
            </div>
          </div>
        </NuxtLink>
      </div>
    </section>
    <h2 v-if="tour" class="wrap h3 tour-h">Every feature in one workbook</h2>
    <section v-if="tour" class="wrap feat">
      <div class="deck-stage" aria-hidden="true">
        <div class="deck">
          <div class="ground" />
          <div
            v-for="(p, i) in plates"
            :key="p.name"
            class="plate"
            :class="{ on: pulled === i }"
            :style="{ '--i': plates.length - 1 - i, '--pull': pulled === i ? 1 : 0, '--tc': p.fg }"
          >
            <i class="edge edge-b" /><i class="edge edge-l" />
            <div class="pf">
              <span class="ttl">{{ p.track.toUpperCase() }}</span
              ><span class="band" /><span class="lbl">{{ p.name }}</span>
            </div>
          </div>
        </div>
      </div>
      <div>
        <div class="dwg2">
          <div class="tt">{{ tour.title.toUpperCase() }}</div>
          <p class="fdesc">{{ tour.description }}</p>
          <ol class="tablist">
            <li
              v-for="(p, i) in plates"
              :key="p.name"
              :style="{ '--tc': p.fg }"
              :class="{ on: pulled === i }"
            >
              <NuxtLink
                :to="`/playground/kitchen-sink?sheet=${i}`"
                @mouseenter="pull(i, true)"
                @focus="pull(i, true)"
                ><span class="sq" /><b>{{ p.name.slice(0, 2) }}</b
                >{{ p.name.slice(3) }}</NuxtLink
              >
            </li>
          </ol>
          <dl>
            <div>
              <dt>BUILDER</dt>
              <dd>createWorkbook()</dd>
            </div>
            <div>
              <dt>SHEETS</dt>
              <dd>{{ plates.length }}</dd>
            </div>
            <div>
              <dt>FILE</dt>
              <dd>{{ kb(tourThumb?.fileSize) }}</dd>
            </div>
          </dl>
        </div>
        <div class="ctas">
          <NuxtLink class="btn btn-primary" to="/playground/kitchen-sink"
            >Open the tour <UIcon name="i-lucide-arrow-right" class="ic"
          /></NuxtLink>
          <a class="btn btn-ghost" :href="getArtifactWorkbookUrl(tour)" download
            ><UIcon name="i-lucide-download" class="ic" /> Download .xlsx</a
          >
        </div>
      </div>
    </section>
  </div>
</template>
